package com.narudzbine.identity.application;

import static org.assertj.core.api.Assertions.*;
import com.narudzbine.shared.api.UuidGenerator;
import com.narudzbine.shared.infrastructure.database.MigrationCommand;
import java.nio.file.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import org.testcontainers.junit.jupiter.*;
import org.testcontainers.postgresql.PostgreSQLContainer;
import org.testcontainers.utility.DockerImageName;

@Testcontainers
class ProofSecretRetentionIT {
    @Container static final PostgreSQLContainer DB=new PostgreSQLContainer(DockerImageName.parse("postgres@sha256:74935e72241653ca55e0414067e6d8763aceb8a810eb51b452253ec3dcfc4336").asCompatibleSubstituteFor("postgres"));
    static final Instant NOW=Instant.parse("2026-10-21T12:00:00Z"),CUTOFF=NOW.minus(Duration.ofDays(30));
    static final UuidGenerator IDS=new UuidGenerator(Clock.fixed(NOW,ZoneOffset.UTC));
    static JdbcTemplate owner;static DriverManagerDataSource runtime;static UUID actor,session;
    ProofSecretRetention service;TransactionTemplate tx;
    enum Family {
        RESET("password_reset_proof","token_hash"),EMAIL("email_change_proof","token_hash"),SETUP("setup_email_proof","token_hash"),DEVICE("device_verification","code_hash"),OAUTH("external_challenge","encrypted_verifier");
        final String table,field;Family(String table,String field){this.table=table;this.field=field;}
    }
    record Proof(Family family,UUID id,UUID parent,UUID delivery){}
    @BeforeAll static void schema(){
        MigrationCommand.migrate(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());var ds=new DriverManagerDataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());owner=new JdbcTemplate(ds);actor=IDS.next();session=IDS.next();
        new TransactionTemplate(new DataSourceTransactionManager(ds)).executeWithoutResult(t->{owner.update("INSERT INTO account_identity(id,kind,email,email_verified,display_name,state) VALUES(?,'PLATFORM_ADMIN',?,true,'Synthetic','ACTIVE')",actor,actor+"@example.com");owner.update("INSERT INTO platform_account(id) VALUES(?)",actor);});
        owner.update("INSERT INTO application_session(id,account_id,transport,token_hash,device_label,created_at,last_qualified_activity_at,absolute_expires_at,auth_at,auth_method_type,credential_generation,security_epoch) VALUES(?,?,'NATIVE',?,'Synthetic',?,?,?,?,'PASSWORD',0,0)",session,actor,hash(session),at(NOW.minusSeconds(40*86400)),at(NOW.minusSeconds(40*86400)),at(NOW.minusSeconds(39*86400)),at(NOW.minusSeconds(40*86400)));
        owner.execute("CREATE ROLE proof_retention_runtime LOGIN PASSWORD 'synthetic-local-only'");owner.execute("GRANT USAGE ON SCHEMA public TO proof_retention_runtime");
        owner.execute("GRANT SELECT ON password_reset_proof,password_reset_delivery,credential_operation,email_change_proof,email_change_delivery,email_change,setup_email_proof,setup_invitation,setup_delivery,setup_intent,device_verification,external_challenge,external_delivery_retention_blocker TO proof_retention_runtime");
        owner.execute("GRANT UPDATE(token_hash) ON password_reset_proof,email_change_proof,setup_email_proof TO proof_retention_runtime");owner.execute("GRANT UPDATE(code_hash) ON device_verification TO proof_retention_runtime");owner.execute("GRANT UPDATE(encrypted_verifier) ON external_challenge TO proof_retention_runtime");
        runtime=new DriverManagerDataSource(DB.getJdbcUrl(),"proof_retention_runtime","synthetic-local-only");
    }
    static Timestamp at(Instant i){return Timestamp.from(i);}
    static byte[] hash(UUID id){try{return java.security.MessageDigest.getInstance("SHA-256").digest(id.toString().getBytes(java.nio.charset.StandardCharsets.US_ASCII));}catch(Exception e){throw new IllegalStateException(e);}}
    @BeforeEach void service(){service=new ProofSecretRetention(new JdbcTemplate(runtime),Clock.fixed(NOW,ZoneOffset.UTC));tx=new TransactionTemplate(new DataSourceTransactionManager(runtime));tx.setTimeout(10);for(Family f:Family.values())sweep(f);}
    int sweep(Family f){return tx.execute(t->switch(f){case RESET->service.reset();case EMAIL->service.email();case SETUP->service.setup();case DEVICE->service.device();case OAUTH->service.oauth();});}
    Proof row(Family f,Instant expiry,boolean blocked,boolean sourcePresent){
        UUID id=IDS.next(),parent=id,delivery=null;Instant created;
        switch(f){
            case RESET->{created=expiry.minusSeconds(1800);UUID op=null;if(blocked){op=IDS.next();owner.update("INSERT INTO credential_operation(id,account_id,kind,state,security_epoch,credential_generation,created_at,updated_at) VALUES(?,?,'RESET','COMPLETED',0,0,?,?)",op,actor,at(created),at(NOW));}
                owner.update("INSERT INTO password_reset_proof(id,account_id,token_hash,email,security_epoch,credential_generation,state,operation_id,created_at,expires_at) VALUES(?,?,?,?,0,0,?,?,?,?)",id,actor,hash(id),actor+"@example.com",blocked?"USED":"INVALIDATED",op,at(created),at(expiry));delivery=id;owner.update("INSERT INTO password_reset_delivery(proof_id,encrypted_token,locale,state,created_at) VALUES(?,?,'en','QUEUED',?)",id,new byte[71],at(created));}
            case EMAIL->{parent=IDS.next();created=expiry.minusSeconds(86400);owner.update("INSERT INTO email_change(id,account_id,request_revision_token,old_email,new_email,security_epoch,credential_generation,state,created_at,expires_at,updated_at) VALUES(?,?,?,?,?,0,0,'EXPIRED',?,?,?)",parent,actor,parent.toString(),actor+"@example.com",parent+"@example.com",at(created),at(expiry),at(blocked?NOW:created));owner.update("INSERT INTO email_change_proof(id,change_id,side,token_hash) VALUES(?,?,'NEW',?)",id,parent,hash(id));delivery=id;owner.update("INSERT INTO email_change_delivery(proof_id,encrypted_token,locale,state,created_at) VALUES(?,?,'en','QUEUED',?)",id,new byte[71],at(created));}
            case SETUP->{parent=IDS.next();created=expiry.minusSeconds(1800);owner.update("INSERT INTO setup_invitation(id,sender_id,recipient_email,country,type,reason,token_hash,state,created_at,updated_at,expires_at) VALUES(?,?,?,'RS','BUYER','Synthetic',?,'PENDING',?,?,?)",parent,actor,parent+"@example.com",hash(parent),at(expiry.minusSeconds(7*86400)),at(created),at(expiry));owner.update("INSERT INTO setup_email_proof(id,invitation_id,generation,token_hash,state,created_at,expires_at) VALUES(?,?,1,?,'ACTIVE',?,?)",id,parent,hash(id),at(created),at(expiry));delivery=IDS.next();owner.update("INSERT INTO setup_delivery(id,invitation_id,generation,proof_id,encrypted_token,recipient_email,locale,state,created_at) VALUES(?,?,1,?,?,?,'en','QUEUED',?)",delivery,parent,id,new byte[71],parent+"@example.com",at(created));if(blocked)owner.update("INSERT INTO setup_intent(id,invitation_id,generation,tenant_id,provider_user_id,account_id,organization_id,payload,request_digest,state,created_at,updated_at) VALUES(?,?,1,?,?,?,?,'Synthetic',?,'UNKNOWN',?,?)",IDS.next(),parent,IDS.next(),IDS.next(),IDS.next(),IDS.next(),hash(id),at(created),at(created));}
            case DEVICE->{created=expiry.minusSeconds(120);owner.update("INSERT INTO device_verification(id,account_id,session_id,installation_id,platform,token_hash,code_hash,environment,project_id,created_at,expires_at,state) VALUES(?,?,?,?,'WEB',?,?,'synthetic','synthetic-project',?,?,?)",id,actor,session,IDS.next(),HexFormat.of().formatHex(hash(id)),HexFormat.of().formatHex(hash(IDS.next())),at(created),at(expiry),blocked?"UNKNOWN":"ACCEPTED");}
            case OAUTH->{created=expiry.minusSeconds(300);owner.update("INSERT INTO external_challenge(id,state_hash,provider,purpose,transport,return_target,browser_binding_hash,encrypted_verifier,state,created_at,expires_at) VALUES(?,?,'GOOGLE','LOGIN','BROWSER','WEB',?,?, ?,?,?)",id,hash(id),hash(IDS.next()),new byte[71],blocked?"CLAIMED":"OPEN",at(created),at(expiry));}
            default->throw new AssertionError();
        }
        if(delivery!=null&&!sourcePresent){String table=f==Family.RESET?"password_reset_delivery":f==Family.EMAIL?"email_change_delivery":"setup_delivery";String key=f==Family.SETUP?"id":"proof_id";owner.update("UPDATE "+table+" SET encrypted_token=NULL WHERE "+key+"=?",delivery);}
        return new Proof(f,id,parent,delivery);
    }
    boolean present(Proof p){return owner.queryForObject("SELECT "+p.family.field+" IS NOT NULL FROM "+p.family.table+" WHERE id=?",Boolean.class,p.id);}
    String metadata(Proof p){return owner.queryForObject("SELECT (to_jsonb(p)-?)::text FROM "+p.family.table+" p WHERE id=?",String.class,p.family.field,p.id);}
    UUID uncertain(Proof p){UUID id=IDS.next();String kind=p.family==Family.RESET?"RESET":p.family==Family.EMAIL?"EMAIL_PROOF":"SETUP";owner.update("INSERT INTO external_fanout(source_kind,source_id,created_at) VALUES(?,?,?)",kind,p.delivery,at(NOW));owner.update("INSERT INTO external_job(id,source_kind,source_id,channel,state,next_attempt_at,terminal_at,created_at) VALUES(?,?,?,'EMAIL','UNKNOWN',?,?,?)",id,kind,p.delivery,at(NOW),at(NOW),at(NOW));return id;}

    @Test void allFiveFamiliesRespectExactThirtyDayCutoffAndPreserveOriginalIdentity(){for(Family f:Family.values()){var old=row(f,CUTOFF,false,false);var fresh=row(f,CUTOFF.plusMillis(1),false,false);if(f==Family.EMAIL)owner.update("UPDATE email_change_proof SET verified_at=? WHERE id=?",at(CUTOFF.minusMillis(1)),old.id);if(f==Family.SETUP)owner.update("UPDATE setup_email_proof SET state='USED' WHERE id=?",old.id);String before=metadata(old);assertThat(sweep(f)).isEqualTo(1);assertThat(present(old)).isFalse();assertThat(present(fresh)).isTrue();assertThat(metadata(old)).isEqualTo(before);assertThat(sweep(f)).isZero();}}
    @Test void unresolvedOrRecentWorkRemainsDeferredForAllFiveFamilies(){for(Family f:Family.values()){var p=row(f,CUTOFF,true,false);String before=metadata(p);assertThat(sweep(f)).isZero();assertThat(present(p)).isTrue();assertThat(metadata(p)).isEqualTo(before);}}
    @Test void encryptedDeliveryCopiesAndUnknownSendsDeferMailProofHashes(){for(Family f:List.of(Family.RESET,Family.EMAIL,Family.SETUP)){var p=row(f,CUTOFF,false,true);assertThat(sweep(f)).isZero();String table=f==Family.RESET?"password_reset_delivery":f==Family.EMAIL?"email_change_delivery":"setup_delivery";owner.update("UPDATE "+table+" SET encrypted_token=NULL WHERE "+(f==Family.SETUP?"id":"proof_id")+"=?",p.delivery);UUID job=uncertain(p);assertThat(sweep(f)).isZero();owner.update("UPDATE external_job SET state='DELIVERED' WHERE id=?",job);assertThat(sweep(f)).isEqualTo(1);assertThat(present(p)).isFalse();}}
    @Test void oneThousandBoundConvergesWithProofAndOperationIdentityRetained(){
        var ids=owner.queryForList("INSERT INTO password_reset_proof(id,account_id,token_hash,email,security_epoch,credential_generation,state,created_at,expires_at) SELECT id,?,decode(md5(id::text)||md5(id::text),'hex'),?,0,0,'INVALIDATED',?,? FROM(SELECT gen_random_uuid() AS id FROM generate_series(1,1006)) s RETURNING id",UUID.class,actor,actor+"@example.com",at(CUTOFF.minusSeconds(1800)),at(CUTOFF));
        assertThat(sweep(Family.RESET)).isEqualTo(1000);assertThat(owner.queryForObject("SELECT count(*) FROM password_reset_proof WHERE id=ANY(?) AND token_hash IS NOT NULL",Integer.class,(Object)ids.toArray(UUID[]::new))).isEqualTo(6);assertThat(sweep(Family.RESET)).isEqualTo(6);assertThat(owner.queryForObject("SELECT count(*) FROM password_reset_proof WHERE id=ANY(?)",Integer.class,(Object)ids.toArray(UUID[]::new))).isEqualTo(1006);
    }
    @Test void twoWorkersSkipRealLockedTargetsAcrossAllFiveFamilies()throws Exception{
        var held=new ArrayList<Proof>();var free=new ArrayList<Proof>();for(Family f:Family.values()){held.add(row(f,CUTOFF,false,false));free.add(row(f,CUTOFF,false,false));}
        try(var c=owner.getDataSource().getConnection()){c.setAutoCommit(false);for(var p:held)try(var q=c.prepareStatement("SELECT id FROM "+p.family.table+" WHERE id=? FOR UPDATE")){q.setObject(1,p.id);q.execute();}try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->Arrays.stream(Family.values()).mapToInt(this::sweep).sum());var b=pool.submit(()->Arrays.stream(Family.values()).mapToInt(this::sweep).sum());assertThat(a.get(10,TimeUnit.SECONDS)+b.get(10,TimeUnit.SECONDS)).isEqualTo(5);}for(var p:held)assertThat(present(p)).isTrue();for(var p:free)assertThat(present(p)).isFalse();c.rollback();}for(Family f:Family.values())assertThat(sweep(f)).isEqualTo(1);
    }
    @Test void initialSecretOneWayRestorationMetadataAndDeleteGuardsRemainStrict(){for(Family f:Family.values()){var p=row(f,CUTOFF,false,false);assertThatThrownBy(()->owner.update("UPDATE "+f.table+" SET "+f.field+"=NULL,id=? WHERE id=?",IDS.next(),p.id)).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(sweep(f)).isEqualTo(1);assertThatThrownBy(()->owner.update("INSERT INTO "+f.table+" SELECT (jsonb_populate_record(NULL::"+f.table+",to_jsonb(p)-?)).* FROM "+f.table+" p WHERE id=?",f.field,p.id)).isInstanceOf(org.springframework.dao.DataAccessException.class).hasStackTraceContaining("Initial proof secret required");Object value=f==Family.DEVICE?"a".repeat(64):f==Family.OAUTH?new byte[71]:new byte[32];assertThatThrownBy(()->owner.update("UPDATE "+f.table+" SET "+f.field+"=? WHERE id=?",value,p.id)).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThatThrownBy(()->owner.update("DELETE FROM "+f.table+" WHERE id=?",p.id)).isInstanceOf(org.springframework.dao.DataAccessException.class);}}
    @Test void retiredSecretsCannotAuthorizeConsumptionButInvalidationStillWorks(){
        var reset=row(Family.RESET,CUTOFF,false,false);var setup=row(Family.SETUP,CUTOFF,false,false);var email=row(Family.EMAIL,CUTOFF,false,false);var device=row(Family.DEVICE,CUTOFF,false,false);var oauth=row(Family.OAUTH,CUTOFF,false,false);UUID active=IDS.next();owner.update("INSERT INTO password_reset_proof(id,account_id,token_hash,email,security_epoch,credential_generation,state,created_at,expires_at) VALUES(?,?,?,?,0,0,'ACTIVE',?,?)",active,actor,hash(active),actor+"@example.com",at(CUTOFF.minusSeconds(1800)),at(CUTOFF));for(Family f:Family.values())sweep(f);
        assertThatThrownBy(()->owner.update("UPDATE password_reset_proof SET state='USED' WHERE id=?",active)).isInstanceOf(org.springframework.dao.DataAccessException.class).hasStackTraceContaining("Retired proof cannot be consumed");owner.update("UPDATE password_reset_proof SET state='INVALIDATED' WHERE id=?",active);
        UUID completed=IDS.next(),used=IDS.next();owner.update("INSERT INTO credential_operation(id,account_id,kind,state,security_epoch,credential_generation,created_at,updated_at) VALUES(?,?,'RESET','COMPLETED',0,0,?,?)",completed,actor,at(CUTOFF.minusSeconds(1800)),at(CUTOFF));owner.update("INSERT INTO password_reset_proof(id,account_id,token_hash,email,security_epoch,credential_generation,state,operation_id,created_at,expires_at) VALUES(?,?,?,?,0,0,'USED',?,?,?)",used,actor,hash(used),actor+"@example.com",completed,at(CUTOFF.minusSeconds(1800)),at(CUTOFF));
        String operationBefore=owner.queryForObject("SELECT to_jsonb(o)::text FROM credential_operation o WHERE id=?",String.class,completed);assertThat(sweep(Family.RESET)).isEqualTo(1);assertThat(owner.queryForObject("SELECT token_hash IS NULL AND state='USED' AND operation_id=? FROM password_reset_proof WHERE id=?",Boolean.class,completed,used)).isTrue();assertThat(owner.queryForObject("SELECT to_jsonb(o)::text FROM credential_operation o WHERE id=?",String.class,completed)).isEqualTo(operationBefore);
        assertThatThrownBy(()->owner.update("UPDATE email_change_proof SET verified_at=? WHERE id=?",at(NOW),email.id)).isInstanceOf(org.springframework.dao.DataAccessException.class).hasStackTraceContaining("Retired proof cannot be consumed");
        assertThatThrownBy(()->owner.update("UPDATE setup_email_proof SET state='USED' WHERE id=?",setup.id)).isInstanceOf(org.springframework.dao.DataAccessException.class).hasStackTraceContaining("Retired proof cannot be consumed");
        assertThatThrownBy(()->owner.update("UPDATE device_verification SET state='CONSUMED' WHERE id=?",device.id)).isInstanceOf(org.springframework.dao.DataAccessException.class).hasStackTraceContaining("Retired proof cannot be consumed");
        assertThatThrownBy(()->owner.update("UPDATE external_challenge SET state='CLAIMED' WHERE id=?",oauth.id)).isInstanceOf(org.springframework.dao.DataAccessException.class).hasStackTraceContaining("Retired proof cannot be consumed");
        owner.update("UPDATE setup_email_proof SET state='INVALIDATED' WHERE id=?",setup.id);assertThat(present(setup)).isFalse();assertThat(present(reset)).isFalse();
    }
    @Test void deterministicSecondRowFailureRollsBackEarlierClearing(){
        var a=row(Family.RESET,CUTOFF,false,false);var b=row(Family.RESET,CUTOFF,false,false);owner.execute("CREATE FUNCTION synthetic_proof_failure() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE seen integer:=coalesce(nullif(current_setting('synthetic.proof_seen',true),''),'0')::integer;BEGIN PERFORM set_config('synthetic.proof_seen',(seen+1)::text,true);IF seen=1 THEN RAISE EXCEPTION 'Synthetic second-row failure';END IF;RETURN NEW;END $$");owner.execute("CREATE TRIGGER tr_synthetic_proof_failure BEFORE UPDATE ON password_reset_proof FOR EACH ROW EXECUTE FUNCTION synthetic_proof_failure()");try{assertThatThrownBy(()->sweep(Family.RESET)).isInstanceOf(org.springframework.dao.DataAccessException.class).hasStackTraceContaining("second-row failure");assertThat(present(a)).isTrue();assertThat(present(b)).isTrue();}finally{owner.execute("DROP TRIGGER tr_synthetic_proof_failure ON password_reset_proof");owner.execute("DROP FUNCTION synthetic_proof_failure()");}assertThat(sweep(Family.RESET)).isEqualTo(2);
    }
    @Test void aggregatePreviewRunsReadOnlyAndMakesDeferralObservable()throws Exception{
        var p=row(Family.EMAIL,CUTOFF,false,false);row(Family.OAUTH,CUTOFF,true,false);String source=Files.readString(Path.of(System.getProperty("basedir"),"retention/proof-secret-preview.sql")).replace("\r\n","\n");String sql=source.substring(source.indexOf("WITH cutoff"),source.indexOf(";\nROLLBACK")).replace(":'retention_at'","'"+NOW+"'");try(var c=runtime.getConnection()){c.setReadOnly(true);c.setAutoCommit(false);try(var q=c.createStatement()){q.setQueryTimeout(10);try(var r=q.executeQuery(sql)){int families=0;while(r.next()){families++;if(r.getString("family").equals("email"))assertThat(r.getLong("eligible_secrets")).isEqualTo(1);if(r.getString("family").equals("oauth"))assertThat(r.getLong("deferred_work")).isGreaterThanOrEqualTo(1);}assertThat(families).isEqualTo(5);assertThat(r.getMetaData().getColumnCount()).isEqualTo(4);}}c.rollback();}assertThat(present(p)).isTrue();
    }
    @Test void definiteLateCompletionMakesAnOAuthChallengeEligibleWithoutChangingBindings(){var p=row(Family.OAUTH,CUTOFF,true,false);String before=metadata(p);assertThat(sweep(Family.OAUTH)).isZero();owner.update("UPDATE external_challenge SET state='COMPLETED' WHERE id=?",p.id);assertThat(sweep(Family.OAUTH)).isEqualTo(1);assertThat(present(p)).isFalse();assertThat(metadata(p)).isEqualTo(before.replace("CLAIMED","COMPLETED"));}
}
